  public function getProtocolBase()
  {
  	$http = 'http';
  	if(!empty($_SERVER["HTTPS"])){
  		$http .= "s";
  	}
  	if ($_SERVER["SERVER_PORT"])
  		$server = $http . "://".$_SERVER["HTTP_HOST"] .':'. $_SERVER["SERVER_PORT"];
  	else
  		$server = $http . "://".$_SERVER["HTTP_HOST"];
  
  	return $server;
  }   
  	
