  public function executeUpdateAprobarAll()
  {
    $facturaestado_id = $this->getRequestParameter('facturaestado_id');
    $udestino = $this->getRequestParameter('usuario_proceso');
    $nprocessupdate = -1;
    //echo "HOLA...";exit;    
    //**********************************************************************************************
    switch($facturaestado_id){
        case 1://supervisiores
            $estado_factura = 9;
            $fproceso_id = 2;
        break;
        case 9://directores
            $estado_factura = 10;
            $fproceso_id = 4;
        break;
		case 10://contabilidad
            $estado_factura = 11;
            $fproceso_id = 6;
        break;
		case 11://auxiliar contabilidad
            $estado_factura = 12;
            $fproceso_id = 3;
        break;
        case 12:
            $estado_factura = 2;  
            $fproceso_id = 14;
            $udestino = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        break;        
        default:
            return $this->redirect($this->getRequest()->getScriptName().'/factura/aprobarAll?cod_msg=1');
        break;
    }
    //*****************************************************************************************************
    $uaprueba = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');    
    $nota = $this->getRequestParameter('observaciones');
    $this->cod_msg = 1;
    //*****************************************************************************************************
    $faprobadas_data = array();
    //*****************************************************************************************************
	$alias_web = ParametroPeer::retrieveByPk(12)->getValortexto();
	$path_data = $this->getBasicUrlAttachFacturas();
	$directorio_entidad = $alias_web . $path_data['basic_path'];
	$directorio_temp = $path_data['temp_path'];
	$directorio_target = $path_data['full_path'];
	//*****************************************************************************************************
	$files = array();
	$files_adjuntos = preg_split("/[,]+/",trim($this->getRequestParameter('ruta')), -1, PREG_SPLIT_NO_EMPTY);
	foreach ($files_adjuntos as $result){
		$filenamesource = $directorio_temp . DIRECTORY_SEPARATOR . $result;
		if(file_exists($filenamesource)){
			$directorio_final = simad_util::createPath($directorio_target);            
			$filenametarget = $directorio_final . DIRECTORY_SEPARATOR . $result;
			//*********************************************************************************
			copy($filenamesource, $filenametarget);
			unlink($filenamesource);
			//*********************************************************************************
			if(trim($result) != ""){
				$files[] = $directorio_entidad.'/'.$result;
			}
		}
	}
	//*****************************************************************************************************
    $facturas_aprobacion = $this->getFacturaMarcaByEstado($facturaestado_id,$uaprueba);	
	while($object = $facturas_aprobacion->fetch()){
		$factura_id = $object[0];
        if(is_numeric($factura_id)){            
            $rptadd = $this->insertaVitacora($estado_factura,$uaprueba,$udestino,$factura_id,$fproceso_id,$nota,$nprocessupdate);
            $objfactura = FacturaPeer::retrieveByPk($factura_id);
            if(trim($rptadd)){
                //*****************************************************************************************
				if(count($files)){
					$files_url = implode(",",$files);
					$objfactura->setRuta($objfactura->getRuta().','.$files_url);
					$objfactura->save();
				}
                //*****************************************************************************************                
                if(trim($udestino)){
                    $encabezado_cuerpo = "Este es un mensaje para informarle que se le ha asignado la siguiente factura:";
                	$this->envioEmail($objfactura->getPrimaryKey(), trim($udestino),$encabezado_cuerpo);
                }
            }
            //*********************************************************************************************
            if($this->cod_msg != 3){ $this->cod_msg = 2; }
            //*********************************************************************************************
        }else{
            $this->cod_msg = 3;
        }
    }
    //*****************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/factura/aprobarAll?cod_msg='.$this->cod_msg);
    //*****************************************************************************************************
  }
    
