  public function executeLoadDataForItem()
  {
    //**********************************************************************************************
    $facturatipo_id = $this->getRequestParameter('factura_tipo_id');
    $factura_id = $this->getRequestParameter('factura_id');
    //**********************************************************************************************
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
	$regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
	//**********************************************************************************************
    $listallreg = $this->getUser()->checkPerm('FACTURAS_USUARIOS_RECEPTORES_REGIONALES', $usuariologuiado);
	$listregbyent = $this->getUser()->checkPerm('FACTURAS_USUARIOS_RECEPTORES_TODAS_ENTIDADES', $usuariologuiado);
  	//**********************************************************************************************
    $c = new Criteria();
    $c->setDistinct();
    //**********************************************************************************************
    $c->addJoin(FactProcesoPorTipoPeer::FACTURAPROCESO_ID,FacturaReceptorPeer::FACTURAPROCESO_ID,Criteria::INNER_JOIN);
    $c->addJoin(FacturaReceptorPeer::USUARIO_ID,UsuarioPeer::USUARIO_ID,Criteria::INNER_JOIN);
	$c->addJoin(FacturaReceptorPeer::REGIONAL_ID,RegionalPeer::REGIONAL_ID,Criteria::INNER_JOIN);
    $c->add(FactProcesoPorTipoPeer::FACTURATIPO_ID,$facturatipo_id);
	$c->add(UsuarioPeer::ESTADOUSUARIO_ID,1);
	//**********************************************************************************************
	if(!$listregbyent){
		if($listallreg){
			$c->add(RegionalPeer::ENTIDAD_ID, $entidad_conectado);
		}else{
			$c->add(FacturaReceptorPeer::REGIONAL_ID, $regional_conectado);
		}
	}
	//**********************************************************************************************
	$c->addAscendingOrderByColumn(UsuarioPeer::NOMBRE);
	$c->addAscendingOrderByColumn(UsuarioPeer::APELLIDO);
    //**********************************************************************************************
    $c->clearSelectColumns();
    $c->addSelectColumn(UsuarioPeer::USUARIO_ID);
    $c->addSelectColumn(UsuarioPeer::NOMBRE);
    $c->addSelectColumn(UsuarioPeer::APELLIDO);
	$c->addSelectColumn(RegionalPeer::DESCRIPCION);
    //**********************************************************************************************
    $this->configusuarios = UsuarioPeer::doSelectStmt($c); 
    //**********************************************************************************************
    $c1 = new Criteria();
    $c1->add(FactVariablePeer::FACTURATIPO_ID,$facturatipo_id);
    $c1->add(FactVariablePeer::ES_ACTUAL,1);
    $c1->addAscendingOrderByColumn(FactVariablePeer::ORDEN);
    $this->variablesproceso = FactVariablePeer::doSelect($c1);
    //**********************************************************************************************
    $this->factura = new Factura();
    if($factura_id){
        $this->factura = FacturaPeer::retrieveByPK($factura_id);
    }
  }
  
  public function executeUploadFile()
  { 
  	if ($this->getRequest()->hasFiles()){
        $factura_id = $this->getRequestParameter('factura_id');
        $file_tmp = $this->getRequest()->getFileName('file');
        if(empty($file_tmp)){
            $this->redirect('factura/fileImagen?factura_id='.$factura_id.'&qfile='.md5("nofile"));
        }
		//*****************************************************************************************
    	$factura = FacturaPeer::retrieveByPk($factura_id);
		$path_data = $this->getBasicUrlAttachFacturas();
    	//*****************************************************************************************
		$file_vars = pathinfo($file_tmp);
		$util_simad = new simad_util();
		$fileName = $util_simad->clean_name_file($file_vars);
        $directorio = simad_util::createPath($path_data['full_path']);
		//*****************************************************************************************
        $cons    = $this->getNewConsecutivo();
		$this->getRequest()->moveFile('file', $directorio.DIRECTORY_SEPARATOR.$cons.'_'.$fileName);
        //*****************************************************************************************
        if(!file_exists($directorio.DIRECTORY_SEPARATOR.$cons.'_'.$fileName)){
            $this->redirect('factura/fileImagen?factura_id='.$factura_id.'&qfile='.md5("exuploadfile"));
        }
        //*****************************************************************************************
		$this->fileName = $cons.'_'.($fileName);
		$datos_archivo = pathinfo(($fileName));
		$this->fileNameOriginal  = trim($datos_archivo['filename']);
		//*****************************************************************************************
		$file_existentes = $factura->getRuta();
		$alias_dir = ParametroPeer::retrieveByPk(12)->getValortexto().$path_data['basic_path'];
		if($file_existentes != ""){				 		      			              			  			 	
			$file_existentes .= ",".$alias_dir.'/'.$cons.'_'.($fileName);    						
		}else{
			$file_existentes = $alias_dir.'/'.$cons.'_'.$fileName;	
		}
		$factura->setRuta($file_existentes);
		//*****************************************************************************************
		if(in_array($factura->getFacturaestadoId(), array(13))){
			$factura->setCodigoBarras($this->fileNameOriginal);
		}
		//*****************************************************************************************
		$factura->save();			     
    } 	         
  }
  
