  public function getBasicUrlAttachFacturas()
  {
	$array_url = array();
	//*****************************************************************************************
	$usuariologuiado = $this->getUser()->getAttribute('username', '', 'subscriber');
	$entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
	$regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
	$periodo = date("Y");
	//*****************************CREANDO ESTRUCTURA DE DIRECTORIOS***************************
	$entidad = EntidadPeer::retrieveByPk($entidad_conectado);
	$regional = RegionalPeer::retrieveByPk($regional_conectado);
	$dirRaiz = ParametroPeer::retrieveByPk(9)->getValortexto();
	$dir_tmp  = ParametroPeer::retrieveByPk(65)->getValortexto();
	//*****************************************************************************************
	$entidad_text = trim($entidad->getDirectorioName()) ? $entidad->getDirectorioName() . "/" : "";
	$regional_text = trim($regional->getDirectorioName()) ? $regional->getDirectorioName() . "/" : "";
	$basic_path = $entidad_text . $regional_text .'Facturas/' . $periodo;    	
	$directorio_entidad = $dirRaiz . $basic_path;
	$directorio_temp = $dirRaiz.$entidad_text.$dir_tmp;
	//*****************************************************************************************
	$array_url['basic_path'] = $basic_path;
	$array_url['full_path'] = $directorio_entidad;
	$array_url['temp_path'] = $directorio_temp;
	//*****************************************************************************************
	return $array_url;
  }
  
  public function executeDzFileUpload()
  {    
    $data_array = array();    
  	if (!empty($_FILES))
    {
        //***************************************************************************************
      	$dirRaiz = ParametroPeer::retrieveByPk(9)->getValortexto();
      	$dirTemp = ParametroPeer::retrieveByPk(65)->getValortexto();
      	//***************************************************************************************
      	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
      	$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
      	$entidad_text = $usuario->getRegional()->getEntidad()->getDirectorioName();
		$entidad_text = trim($entidad_text) ? trim($entidad_text).DIRECTORY_SEPARATOR : "";
      	$path = $dirRaiz.$entidad_text.$dirTemp.DIRECTORY_SEPARATOR;        
        $directorio = realpath(simad_util::createPath($path));      	        
        //***************************************************************************************
        $file_vars = pathinfo($_FILES['file']['name']);
        $util_simad = new simad_util();
        $fileName = $util_simad->clean_name_file($file_vars);
        $tempFile = $_FILES['file']['tmp_name'];
        $cons    = $this->getNewConsecutivo();
        //***************************************************************************************
        move_uploaded_file($tempFile,$directorio.DIRECTORY_SEPARATOR.$cons.'_'.$fileName);
        $data_array['name'] = $cons.'_'.$fileName;      
        //***************************************************************************************
        $this->getResponse()->setContentType('application/json');
        $data_json = json_encode($data_array);
        return $this->renderText($data_json);
    }else{
        $this->getResponse()->setContentType('application/json');
        $data_json = json_encode($data_array);
        return $this->renderText($data_json);
    }
  }    
  
  function string2url($cadena) {        
    	$cadena = preg_replace('#([^.a-z0-9]+)#i','-', $cadena);
        $cadena = preg_replace('#-{2,}#','-',$cadena);
        $cadena = preg_replace('#-$#','',$cadena);
        $cadena = preg_replace('#^-#','',$cadena);
    	return $cadena; 
    }
    
    public function getNewConsecutivo()
    {
    	$cons = ParametroPeer::retrieveByPk(8);
    	$regId = $cons->getValorNumerico();
    	if($regId > 0){
    		$cons->setValorNumerico($regId+1);
    		$cons->save();
    	}
    	return $regId;		
    }  
  
