    $regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');    
    $factura = $this->factura = FacturaPeer::retrieveByPk(trim($this->getRequestParameter('factura_id')));
    $factura_id = $factura->getPrimaryKey();
    //*******************************************************************************    
    $stateview = trim($this->getRequestParameter('viewstate'));
    $backid = trim($this->getRequestParameter('backid'));
    $dataShared = ContenidoUnidadDocumentalPeer::getFormatSharedComUrlView($backid,$factura_id,$stateview,13);
    //*******************************************************************************
    $listall = $this->getUser()->checkPerm('FACTURAS_VER_TODAS', $usuariologuiado);    
    //*******************************************************************************
    if(!$listall){
        if(!$dataShared['IsViewValid']){
            if(!FacturaPeer::getAccessByUserDestino($factura->getPrimaryKey())){
                if(!FacturaPeer::getAccessByUserOrigen($factura->getPrimaryKey())){
                    $this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');             	
                }
            }
        }
    }    
    //*******************************************************************************
    $this->requisitorName = $this->getRequisitor($factura->getPrimaryKey());
    //*******************************************************************************
	$c = new Criteria();
    $c->add(FacturaVitacoraPeer::FACTURA_ID,$factura->getPrimaryKey() );
    $factura_vitacoras = $this->factura_vitacoras = FacturaVitacoraPeer::doSelect($c);
    //*******************************************************************************
    $usuarioVitacoraOrigen = array();
    $usuarioVitacoraDestino = array();
    $i=0;
	//*******************************************************************************
    foreach($factura_vitacoras as $factura_vitacora){
	 	  $usuarioVitacoraOrigen[$i] = $this->getUsuarioVitacora(1,$factura_vitacora->getPrimaryKey());//1 es origen
	 	  $usuarioVitacoraDestino[$i] = $this->getUsuarioVitacora(2,$factura_vitacora->getPrimaryKey());// 2 es destino
	 	  $i++;
	}
	//*******************************************************************************
	$this->usuarioVitacoraOrigen = $usuarioVitacoraOrigen;
    $this->usuarioVitacoraDestino = $usuarioVitacoraDestino;
    $this->dataShared = $dataShared;
	$this->forward404Unless($this->factura);
  }
  
