  public function executeCrear()
  {
    if (!$this->getRequestParameter('factura_id'))
    {
      $factura = new Factura();
    }
    else
    {
      $factura = FacturaPeer::retrieveByPk($this->getRequestParameter('factura_id'));
      $this->forward404Unless($factura);
    }

    //$factura->setFacturaId($this->getRequestParameter('factura_id'));
    $factura->setProveedorId($this->getRequestParameter('proveedor_id') ? $this->getRequestParameter('proveedor_id') : null);
    $factura->setFacturaestadoId($this->getRequestParameter('facturaestado_id') ? $this->getRequestParameter('facturaestado_id') : null);
    $factura->setNumero($this->getRequestParameter('numero'));
    $factura->setValorFactura($this->getRequestParameter('valor_factura'));
    $factura->setValorFacturaUs($this->getRequestParameter('valor_factura_us'));
    $factura->setValorFacturaE($this->getRequestParameter('valor_factura_e'));
    $factura->setConcepto($this->getRequestParameter('concepto'));
    $factura->setObservaciones($this->getRequestParameter('observaciones'));
    if ($this->getRequestParameter('fecha_recibido'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_recibido'), $this->getUser()->getCulture());
      $factura->setFechaRecibido($this->getRequestParameter('fecha_recibido'));
    }
    if ($this->getRequestParameter('hora_recibido'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('hora_recibido'), $this->getUser()->getCulture());
      $factura->setHoraRecibido($this->getRequestParameter('hora_recibido'));
    }
    if ($this->getRequestParameter('fecha_radicado'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_radicado'), $this->getUser()->getCulture());
      $factura->setFechaRadicado($this->getRequestParameter('fecha_radicado'));
    }
    $factura->setCodigoBarras($this->getRequestParameter('codigo_barras'));
    $factura->setAsunto($this->getRequestParameter('asunto'));
    $factura->setRuta($this->getRequestParameter('ruta'));
    $factura->setNumeroRadicacion($this->getRequestParameter('numero_radicacion'));
    $factura->setRadicado($this->getRequestParameter('radicado'));
    $factura->setMarca($this->getRequestParameter('marca'));
    $factura->setMarcacausacion($this->getRequestParameter('marcacausacion'));
    $factura->setCausadaensap($this->getRequestParameter('causadaensap'));
    $factura->save();
    return $this->redirect($this->getRequest()->getScriptName().'/factura/show?factura_id='.$factura->getFacturaId());
  }
  
  
  public function executeUpdate()
  {
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $currentForm = "factura/edit";
  	$this->verificaPrilegio($currentForm); 
    //********************************************************************************************
	$factura = FacturaPeer::retrieveByPk($this->getRequestParameter('factura_id'));
    $procesofactura = 1;
    $tipofactura_id = $factura->getFacturatipoId();
    $facturaestado_id = $factura->getFacturaestadoId();
    $usuarioCausador = "";
    $obs = $factura->getObservaciones()."|".$this->getRequestParameter('observaciones');
    $this->forward404Unless($factura);
    //********************************************************************************************    
    $facturatipo_id = trim($this->getRequestParameter('factura_tipo_id'));
    $factproceso_tipo = FactProcesoPorTipoPeer::getFactProcesoByTipo($tipofactura_id,$facturaestado_id);
    //********************************************************************************************
    if($factproceso_tipo != null){
        $procesofactura = $factproceso_tipo->getFacturaprocesoId();
    }
    //********************************************************************************************
    $factura->setProveedorId($this->getRequestParameter('proveedor_id') ? $this->getRequestParameter('proveedor_id') : null);
    $factura->setFacturaestadoId($this->getRequestParameter('facturaestado_id') ? $this->getRequestParameter('facturaestado_id') : null);
    $factura->setFacturatipoId($this->getRequestParameter('factura_tipo_id'));
    $factura->setNumero($this->getRequestParameter('numero'));
    $factura->setFormarecepcionId($this->getRequestParameter('formarecepcion_id'));
	$factura->setAsunto($this->getRequestParameter('asunto'));
    $factura->setDocCausacion(trim($this->getRequestParameter('doc_causacion')) ? trim($this->getRequestParameter('doc_causacion')) : $factura->getDocCausacion());
    //********************************************************************************************
    if(str_replace(",","",$this->getRequestParameter('valor_factura')) != ""){	
        $factura->setValorFactura(str_replace(",","",$this->getRequestParameter('valor_factura')));
        $factura->setValorFacturaUs(null);
        $factura->setValorFacturaE(null);
    }
    if(str_replace(",","",$this->getRequestParameter('valor_factura_us')) != ""){
        $factura->setValorFacturaUs(str_replace(",","",$this->getRequestParameter('valor_factura_us')));
        $factura->setValorFactura(null);
        $factura->setValorFacturaE(null);
    }
    if(str_replace(",","",$this->getRequestParameter('valor_factura_e')) != ""){
        $factura->setValorFacturaE(str_replace(",","",$this->getRequestParameter('valor_factura_e')));
        $factura->setValorFactura(null);
        $factura->setValorFacturaUs(null);
    }    
    //********************************************************************************************
    if ($this->getRequestParameter('fecha_recibido'))
    {
      $fecha_recibido = $this->getRequestParameter('fecha_recibido');
      $factura->setFechaRecibido(date("Y-m-d G:i:s",strtotime($fecha_recibido)));
    }
    //********************************************************************************************
    if($this->getRequestParameter('codigo_barras')!=""){
      $factura->setCodigoBarras($factura->getCodigoBarras().','.$this->getRequestParameter('codigo_barras'));
    }
    //*********************************************************************************************
    if(trim($this->getRequestParameter('ruta_text')) != ""){
    	//*****************************************************************************************
		$alias_name = ParametroPeer::retrieveByPk(12)->getValortexto();
		$path_data = $this->getBasicUrlAttachFacturas();		
    	$alias_dir = $alias_name . $path_data['basic_path'];
    	//*****************************************************************************************
		$files = array();
		$files_adjuntos = preg_split("/[,]+/",trim($this->getRequestParameter('ruta_text')), -1, PREG_SPLIT_NO_EMPTY);
		foreach ($files_adjuntos as $result){
			if(trim($result) != ""){
				$files[] = $alias_dir.'/'.$result;
			}
		}
        //************************************************************************
        if(count($files)){
		  $factura->setRuta($factura->getRuta().','.implode(",",$files));
        }
	}    	
	//********************************************************************************************
    $factura->save();
	//********************************************************************************************
    if(!in_array($facturaestado_id,array(3,5,12,18))){
        if($this->getRequestParameter('usuario_causador')){
            $usuarioCausador = UsuarioPeer::retrieveByPk($this->getRequestParameter('usuario_causador'));
            $usuarioOrigen = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
            $this->insertaVitacora($facturaestado_id,$usuarioOrigen,$usuarioCausador->getUsuarioId(),$factura->getPrimaryKey(),$procesofactura,$obs) ;
    	}else{
    	   $factura->setObservaciones($obs);
           $factura->save();
    	} 
    }else{
        $factura->setObservaciones($obs);
        $factura->save();
    }
    //***********************************************************************************************************
    $requisitor_id = trim($this->getRequestParameter('destinatarioId'));
    $requisitor_id_anterior = $this->getRequestParameter('destinatarioIdAnterior');
    if($requisitor_id != "" /*&& $requisitor_id_anterior != $requisitor_id*/){//ejecuta solo si viene requisitor
        $c = new Criteria();
        $c->addJoin(FactUsuarioRequisitorPeer::FACTURAVITACORA_ID,FacturaVitacoraPeer::FACTURAVITACORA_ID);
        $c->add(FacturaVitacoraPeer::FACTURA_ID,$this->getRequestParameter('factura_id'));        
        $udate_requisitor = FactUsuarioRequisitorPeer::doSelectOne($c);
        if($udate_requisitor){
            $udate_requisitor->setUsuarioId($requisitor_id);
            $udate_requisitor->save();
        }else{
            /********************************************************/
            //obtiene  la vitacora
            $c = new Criteria();
            //$c->addJoin(FactUsuarioRequisitorPeer::FACTURAVITACORA_ID,FacturaVitacoraPeer::FACTURAVITACORA_ID);
            $c->add(FacturaVitacoraPeer::FACTURA_ID,$this->getRequestParameter('factura_id'));
            $c->add(FacturaVitacoraPeer::EJECUTADA,false);
            $factura_vitacora = FacturaVitacoraPeer::doSelectOne($c);
            /********************************************************/
            $factura_vitacora_usuario=new FactUsuarioRequisitor();
	        $factura_vitacora_usuario->setFacturaVitacoraRolUsuarioId(3);
	        $factura_vitacora_usuario->setFacturavitacoraId($factura_vitacora->getPrimaryKey());
	        $factura_vitacora_usuario->setUsuarioId($requisitor_id); 
	        $factura_vitacora_usuario->save();            
        }
        //***********************************************************************************************************
        // enviar alerta        
        $encabezado_cuerpo = "Este es un mensaje para informarle que tiene la siguiente factura:";
		$this->envioEmail($factura->getPrimaryKey(), $requisitor_id,$encabezado_cuerpo);
    }
    //***********************************************************************************************************
    if(trim($usuarioCausador)){
        $encabezado_cuerpo = "Este es un mensaje para informarle que se le ha reasignado una factura para su aprobacion, con los siguientes datos:";
        $this->envioEmail($factura->getPrimaryKey(), $usuarioCausador->getPrimaryKey(),$encabezado_cuerpo);
    }
    //***********************************************************************************************************
    //delete variables
    if($factura->getFacturatipoId() != $tipofactura_id){
        $this->DeleteAllVariables($factura->getPrimaryKey());    
        //***********************************************************************************************************
         //Guardar campos dinamicos
         $cv = new Criteria();
         $cv->add(FactVariablePeer::FACTURATIPO_ID,$factura->getFacturatipoId());
         $cv->addAscendingOrderByColumn(FactVariablePeer::ORDEN);
         $field_vars = FactVariablePeer::doSelect($cv);
         foreach($field_vars as $variable){
            $name_element = str_replace(" ","",$variable->getNombre());
            $value_var = $this->getRequestParameter($name_element);
            if(trim($value_var)){
                $variable_value = new FactVariableValues();
                $variable_value->setFacturaId($factura->getPrimaryKey());
                $variable_value->setFactvariableId($variable->getFactvariableId());
                $variable_value->setVariableValue($value_var);
                $variable_value->save();
            }
         }
     }else{
         $cv = new Criteria();
         $cv->add(FactVariablePeer::FACTURATIPO_ID,$factura->getFacturatipoId());
         $cv->addAscendingOrderByColumn(FactVariablePeer::ORDEN);
         $field_vars = FactVariablePeer::doSelect($cv);
         foreach($field_vars as $variable){
            $name_element = str_replace(" ","",$variable->getNombre());
            $value_var = $this->getRequestParameter($name_element);
            if(trim($value_var)){
                $cvv = new Criteria();
                $cvv->add(FactVariableValuesPeer::FACTURA_ID,$factura->getPrimaryKey());
                $cvv->add(FactVariableValuesPeer::FACTVARIABLE_ID,$variable->getPrimaryKey());
                $value_vars = FactVariableValuesPeer::doSelectOne($cvv);
                if($value_vars){
                    $value_vars->setVariableValue($value_var);
                    $value_vars->save();
                }else{
                    $variable_value = new FactVariableValues();
                    $variable_value->setFacturaId($factura->getPrimaryKey());
                    $variable_value->setFactvariableId($variable->getFactvariableId());
                    $variable_value->setVariableValue($value_var);
                    $variable_value->save();
                }
            }else{
                $this->DeleteVariableById($variable->getPrimaryKey(),$factura->getPrimaryKey());
            }
         }
     }
	//**********************************************************************************************************
    $nueva_factura = -1;
    return $this->redirect($this->getRequest()->getScriptName().'/factura/show?factura_id='.$factura->getFacturaId().'&'.md5('nueva_factura').'='.$nueva_factura);
  }
  
  public function DeleteAllVariables($factura_id)
  {
    $conexion = Propel::getConnection();
    $consulta = "DELETE %s WHERE %s=" . $factura_id;
    $consulta = sprintf($consulta, FactVariableValuesPeer::TABLE_NAME, FactVariableValuesPeer::FACTURA_ID);            
    $sentencia = $conexion->prepare($consulta);
    $sentencia->execute();    
  }
  
  public function DeleteVariableById($variablevalue_id,$factura_id)
  {
    $conexion = Propel::getConnection();
    $consulta = "DELETE %s WHERE %s=" . $factura_id . " AND %s=" . $variablevalue_id;    
    $consulta = sprintf($consulta, FactVariableValuesPeer::TABLE_NAME, FactVariableValuesPeer::FACTURA_ID,FactVariableValuesPeer::FACTVARIABLE_ID);
    $sentencia = $conexion->prepare($consulta);
    $sentencia->execute();
  }
  
  public function executeTrashImg()
  {
  	//*********************************************************************************************
    $factura_id = trim($this->getRequestParameter('factura_id'));
  	$factura = FacturaPeer::retrieveByPk($factura_id);
  	$filenamedel = trim($this->getRequestParameter('filenameimg'));
  	$files = preg_split("/[,]+/",$factura->getRuta(), null, PREG_SPLIT_NO_EMPTY);
  	$newurl = array();
  	//*********************************************************************************************
  	foreach ($files as $file){
  		$name_file = basename($file);
  		if($name_file != $filenamedel){
  			$newurl[] = $file;
  		}
  	}
  	//*********************************************************************************************
  	$factura->setRuta(implode(",", $newurl));
  	$factura->save();
    //*********************************************************************************************
    FacturaPeer::addAuditActionImage($factura->getPrimaryKey(),$filenamedel);
  	//*********************************************************************************************
  	return $this->redirect($this->getRequest()->getScriptName().'/factura/deleteImg?factura_id='.$factura->getPrimaryKey());
  	$this->forward404Unless($this->contenido_unidad_documental);
  	//*********************************************************************************************
  }
  
  public function getFacturaMarcaByEstado($estadofactura_id,$marca = 0)
  {
    $c = new Criteria();
    $c->add(FacturaPeer::MARCA,$marca);
    $c->add(FacturaPeer::FACTURAESTADO_ID,$estadofactura_id);
    //**********************************************************************************************
    $c->clearSelectColumns();
    $c->addSelectColumn(FacturaPeer::FACTURA_ID);
    $c->addSelectColumn(FacturaPeer::FACTURAESTADO_ID);
    //**********************************************************************************************
    return FacturaPeer::doSelectStmt($c);
  }
  
  public function getMaxNumRadicacion($regional)
  {
    $periodoActual = date("Y");
    $conexion = Propel::getConnection();
    $consulta = "SELECT MAX(%s) AS max FROM %s WHERE %s=" . $regional . " AND %s=" .$periodoActual;
    $consulta = sprintf($consulta, FacturaPeer::NUMERO_RADICACION, FacturaPeer::TABLE_NAME, FacturaPeer::REGIONAL_ID, FacturaPeer::PERIODO_ID,FacturaPeer::FECHA_RADICADO);
    //**********************************************************************************************
    //echo $consulta;exit;
    $sentencia = $conexion->prepare($consulta);
    $sentencia->execute();
    $resultset = $sentencia->fetch(PDO::FETCH_OBJ);
    return ($resultset->max + 1);
  }

  public function executeUpdatecreate()
  {    
    if (!$this->getRequestParameter('factura_id')){
      $factura = new Factura();
