	$cuentaFacturas1 = FacturaPeer::doCount($ce);
	//*********************************************************************************************  
	$cc = new Criteria();	 
	$cc->add(FacturaPeer::CODIGO_BARRAS,$this->getRequestParameter('codigo_barras'));
	$cuentaFacturas2 = FacturaPeer::doCount($cc);
	//*********************************************************************************************
	$errorFactura="";    
	if($cuentaFacturas1){
		$existeFactura = 1;
		$errorFactura="El numero de factura con el proveedor ya existe en el sistema. ";
	}
	//*********************************************************************************************
	/*if($cuentaFacturas2){
		$existeFactura=2;
		$errorFactura.="El codigo de barras ya existe en el sistema. ";
	}*/
	//*********************************************************************************************
    $factura->setNumero($this->getRequestParameter('numero'));
	$factura->setCodigoBarras(trim($this->getRequestParameter('codigo_barras')) ? trim($this->getRequestParameter('codigo_barras')) : "No Registra");
