  public function insertaVitacora($estado,$usuarioOrigen,$usuarioDestino,$factura_id,$proceso_id,$observaciones,$nprocessupdate=-1,$update_factura=true)
  {
    $factura = FacturaPeer::retrieveByPk($factura_id);
    $updateIsValid = true;
    //*************************************************************************************************
  	if($update_factura){
        $factura->setFacturaestadoId($estado);  
    	$obs2 = $factura->getObservaciones()."|".$observaciones;  
        $factura->setObservaciones($obs2);    
        $factura->save();
        //*********************************************************************************************
        $updateIsValid = $this->updateFactVitacoraEjecutada($factura_id,$nprocessupdate);
    }    
    //*************************************************************************************************
    $estado_close = array(2,3,5,8);
    if($updateIsValid && !in_array($estado,$estado_close)){
    	//inserta  la vitacora
        $factura_vitacora = new FacturaVitacora();
        $factura_vitacora->setFacturaprocesoId($proceso_id);
        $factura_vitacora->setFacturaestadoId($estado);
        $factura_vitacora->setFacturaId($factura->getPrimaryKey());
        $factura_vitacora->setFechaI(date("Y-m-d G:i:s"));
    	$factura_vitacora->setFechaIDate(date("Y-m-d"));
        $factura_vitacora->setObservaciones($observaciones);
        $factura_vitacora->setEjecutada(0);
        $factura_vitacora->save();
        
        //RADICADOR
        $factura_vitacora_usuario = new FacturaVitacoraUsuario();
        $factura_vitacora_usuario->setFacturaVitacoraRolUsuarioId(1);
        $factura_vitacora_usuario->setFacturavitacoraId($factura_vitacora->getPrimaryKey());
        $factura_vitacora_usuario->setUsuarioId($usuarioOrigen);
        $factura_vitacora_usuario->save();
        
        //DESTINATARIO
    	$factura_vitacora_usuario=new FactUsuarioDestino();
        $factura_vitacora_usuario->setFacturaVitacoraRolUsuarioId(2);
        $factura_vitacora_usuario->setFacturavitacoraId($factura_vitacora->getPrimaryKey());
        $factura_vitacora_usuario->setUsuarioId($usuarioDestino);
        $factura_vitacora_usuario->save();
    }elseif($estado == 2 || $estado == 3 ){
        $this->updateFactVitacoraEjecutada($factura_id,$nprocessupdate);
        //*******************************************************************************
        //inserta  la vitacora
        $factura_vitacora = new FacturaVitacora();
        $factura_vitacora->setFacturaprocesoId($proceso_id);
        $factura_vitacora->setFacturaestadoId($estado);
        $factura_vitacora->setFacturaId($factura->getPrimaryKey());
        $factura_vitacora->setFechaI(date("Y-m-d G:i:s"));
        $factura_vitacora->setFechaF(date("Y-m-d G:i:s"));
    	$factura_vitacora->setFechaIDate(date("Y-m-d"));
        $factura_vitacora->setFechaFDate(date("Y-m-d"));
        $factura_vitacora->setObservaciones($observaciones);
        $factura_vitacora->setEjecutada(1);
        $factura_vitacora->save();        
        //RADICADOR
        $factura_vitacora_usuario = new FacturaVitacoraUsuario();
        $factura_vitacora_usuario->setFacturaVitacoraRolUsuarioId(1);
        $factura_vitacora_usuario->setFacturavitacoraId($factura_vitacora->getPrimaryKey());
        $factura_vitacora_usuario->setUsuarioId($usuarioOrigen);
        $factura_vitacora_usuario->save();
        //DESTINATARIO
    	$factura_vitacora_usuario=new FactUsuarioDestino();
        $factura_vitacora_usuario->setFacturaVitacoraRolUsuarioId(2);
        $factura_vitacora_usuario->setFacturavitacoraId($factura_vitacora->getPrimaryKey());
        $factura_vitacora_usuario->setUsuarioId($usuarioDestino);
        $factura_vitacora_usuario->save();
    }
	return 1;
 }
  
    public function getFactProcesoByGen($estadofactselect_id)
    {
        $factura_procesos = array();
        switch($estadofactselect_id)
        {
            case 11;//Causacion
                $factura_procesos[] = 3;
                $factura_procesos[] = 5;
            break;
            case 10;//Contabilidad
                $factura_procesos[] = 6;
                $factura_procesos[] = 5;
            break;
            case 9;//Directores
                $factura_procesos[] = 4;
                $factura_procesos[] = 5;
            break;
            case 12;//Tesoreria
                $factura_procesos[] = 14;
                $factura_procesos[] = 5;
            break;
            case 1;//Supervisiores
                $factura_procesos[] = 2;
                $factura_procesos[] = 5;
            break;
            default:
               $factura_procesos = array();
            break; 
        }
        return $factura_procesos;
    }
    
    public function updateFactVitacoraEjecutada($factura_id,$proceso_id = -1)
    {
        try{
            $this->updateFBitacoraSetFechaFin($factura_id,$proceso_id);
            $conexion = Propel::getConnection();            
			$consulta = "UPDATE %s SET %s=1 WHERE %s=".$factura_id." AND %s <> $proceso_id;";    
			$consulta = sprintf($consulta, FacturaVitacoraPeer::TABLE_NAME,FacturaVitacoraPeer::EJECUTADA,FacturaVitacoraPeer::FACTURA_ID,FacturaVitacoraPeer::FACTURAPROCESO_ID);
            $sentencia = $conexion->prepare($consulta);
            $sentencia->execute();            
            return true;
        }catch (Exception $ex){
        	return false;
        }	 
    }
  
    public function updateFBitacoraSetFechaFin($factura_id,$proceso_id = -1)
    {
        try{
          	$conexion = Propel::getConnection();
          	$consulta = "UPDATE %s SET %s = '".date("Y-m-d G:i:s")."', %s = '".date("Y-m-d")."' WHERE %s=".$factura_id." AND %s = 0 AND %s <> $proceso_id;"; 
			$consulta = sprintf($consulta, FacturaVitacoraPeer::TABLE_NAME,FacturaVitacoraPeer::FECHA_F,FacturaVitacoraPeer::FECHA_F_DATE,FacturaVitacoraPeer::FACTURA_ID,FacturaVitacoraPeer::EJECUTADA,FacturaVitacoraPeer::FACTURAPROCESO_ID);
          	$sentencia = $conexion->prepare($consulta);
            $sentencia->execute();
          	return true;
        }catch (Exception $ex){
        	return false;
        }  	
    }
  
  public function ExistsNumRadicacion($numero_radicacion,$regional_id,$factura_id)
  {
     $c = new Criteria();
     $c->add(FacturaPeer::NUMERO_RADICACION,$numero_radicacion);
     $c->add(FacturaPeer::REGIONAL_ID,$regional_id);
     $c->add(FacturaPeer::PERIODO_ID,date("Y"));
     $c->add(FacturaPeer::FECHA_RADICADO,date("Y-m-01"),Criteria::GREATER_EQUAL);
     $count_num_radicacion = FacturaPeer::doCount($c);
     //********************************************************************
     if($count_num_radicacion){
        return true;
     }else{
        try{
    	  	$conexion = Propel::getConnection();
    	  	$consulta = "UPDATE %s SET %s = ".$numero_radicacion." WHERE %s = ".$factura_id.";";
            $consulta = sprintf($consulta, FacturaPeer::TABLE_NAME, FacturaPeer::NUMERO_RADICACION, FacturaPeer::FACTURA_ID);
    	  	$sentencia = $conexion->prepare($consulta);
            $sentencia->execute();
    	  	return false;
      	}catch (Exception $ex){
      		return true;
      	}
     }
  }
  
