        return $c;
    }
    
    public function executeExportBitacora()
    {
        $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        $dataUser  = UsuarioPeer::retrieveByPK($usuariologuiado);
        $base_path = sfConfig::get('base_simad');
        $factura = FacturaPeer::retrieveByPk($this->getRequestParameter('factura_id'));
        $nomb_file_html = $this->GenFormatoBitacotaFileData($factura);
        //***************************************************************************************
        $this->redirect($base_path.'/generatepdf.php?exportfact='.$nomb_file_html);        
    	$this->forward404Unless($this->unidad_documental);	
    }    
    
