        $sustituciones[12] = $factura->getRadicado();
        $sustituciones[13] = $factura->getDocCausacion();
        $sustituciones[14] = "";
        $sustituciones[15] = ($usuario_solicita->getRegional()->getDescripcion());
        $sustituciones[16] = ($usuario_solicita->getNombreAll());
        $sustituciones[17] = date("Y-m-d G:i:s");
        //*******************************************************************************************
        $tipo_moneda = "";
        $valor_factura = "";
