        $c->addAsColumn('OrigenApellido',"usuario_origen.APELLIDO");//5
        $c->addAsColumn('DestinoNombre',"usuario_destino.NOMBRE");//6
        $c->addAsColumn('DestinoApellido',"usuario_destino.APELLIDO");//7
        $c->addAsColumn('Observaciones',FacturaVitacoraPeer::OBSERVACIONES);//8
        $c->addAsColumn('EstadoEjecucion',FacturaVitacoraPeer::EJECUTADA);//9
        $detalles_bitacora = FacturaVitacoraPeer::doSelectStmt($c);
        //*******************************************************************************************
        $html_contenido = "";
        while($object = $detalles_bitacora->fetch()){
            $html_contenido .= '<tr>
            <td>'.$object[0].'</td>
            <td>'.($object[1]).'</td>
            <td>'.date("Y-m:d G:i:s",strtotime($object[2])).'</td>
            <td>'.date("Y-m:d G:i:s",strtotime($object[3])).'</td>
            <td>'.($object[4].' '.$object[5]).'</td>
            <td>'.($object[6].' '.$object[7]).'</td>
            <td>'.($object[8]).'</td>
            <td class="text-center">'.($object[9] ? 'Ejecutada' : 'Pendiente').'</td></tr>';
        }        
        $sustituciones[14] = $html_contenido;        
        //**********************************REMPLAZAR DATOS EN LA FACTURA****************************
        $template_contents = str_replace($patrones,$sustituciones,$plantilla_contents);
        //********************************************GUARDAR LA PLANTILLA TEMPORAL******************
        // Guarda el RTF generado
        simad_util::createPath($tmp_plantilla);    
        file_put_contents($tmp_plantilla.$name_plantilla_tmp,$template_contents);
        //*******************************************************************************************
        return $name_plantilla_tmp;
    }
}